current_user = frappe.session.user

if current_user and current_user != "Administrator":
    user_roles = frappe.get_all(
        "Has Role",
        filters={"parent": current_user, "parenttype": "User"},
        pluck="role"
    )

    role_to_team = {
        "Support Associate": "L1 Associate Team",
        "Support Senior": "L2 Senior Team",
        "Support Operations Manager": "Sabre CSM Team",
        "Sabre CSM Supervisor": "L3 Supervisor Team",
    }

    matched_team = None
    for role, team in role_to_team.items():
        if role in user_roles:
            matched_team = team
            break

    if matched_team:
        doc.agent_group = matched_team
        frappe.db.set_value(doc.doctype, doc.name, "agent_group", matched_team, update_modified=False)

    already_assigned = frappe.db.exists("ToDo", {
        "reference_type": doc.doctype,
        "reference_name": doc.name,
        "allocated_to": current_user,
        "status": "Open"
    })

    if not already_assigned:
        frappe.call(
            "frappe.desk.form.assign_to.add",
            doctype=doc.doctype,
            name=doc.name,
            assign_to=[current_user],
            description="Ticket created by you",
            ignore_permissions=True
        )
